function FinishedScreen({ points, maxPossiblePoints, highscore, dispatch }) {
  const percentrage = (points / maxPossiblePoints) * 100;

  let emoji;
  if (percentrage === 100) emoji = "🥇";
  if (percentrage >= 80 && percentrage < 100) emoji = "🥈";
  if (percentrage >= 50 && percentrage < 80) emoji = "🥉";
  if (percentrage >= 0 && percentrage < 50) emoji = "😁";
  if (percentrage === 0) emoji = "🤦";

  return (
    <>
      <p className="result">
        You scored <strong>{points}</strong> out of {maxPossiblePoints} (
        {Math.ceil(percentrage)}%)
      </p>
      <p className=" highscore">(Highscore: {highscore} points)</p>
      <button
        className="btn btn-ui"
        onClick={() => dispatch({ type: "finish" })}
      >
        Finish
      </button>
    </>
  );
}

export default FinishedScreen;
